function updateFileName(input){const fileName=input.files[0]?input.files[0].name:"No file chosen";if(document.getElementById("file-name").textContent=fileName,input.files&&input.files[0]){const reader=new FileReader;reader.onload=function(e){const profileContainer=document.querySelector(".profile-image-container");profileContainer.querySelector(".profile-image")?profileContainer.querySelector(".profile-image").src=e.target.result:profileContainer.querySelector(".profile-placeholder")&&(profileContainer.innerHTML='<img src="'+e.target.result+'" alt="Profile Image" class="profile-image">')},reader.readAsDataURL(input.files[0])}}
